import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Vector2 } = ctx.THREE;

  const group = new Group();
  group.userData.cleanup = () => {
    // No GSAP timelines, no special event handlers
    material.dispose();
    geometry.dispose();
  };

  // Atlas region: 512x320 (from 0,0 in atlas)
  // Aspect ratio: 512/320 = 1.6
  const aspectRatio = 512 / 320;
  const height = 1.5; // Scene-unit height for a card
  const width = height * aspectRatio;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();

  // Load and apply the ceramic grain texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Set up atlas UV coordinates
    // Atlas region: source (0, 0) to (512, 320) in a larger atlas
    // Assuming atlas is 1024x1024, UV bounds: x [0, 0.5], y [0.3125, 0.625] (inverted for WebGL y-up)
    // For a 512x512 atlas: x [0, 1], y [0, 0.625] or normalized to region
    texture.offset = new Vector2(0, 0);
    texture.repeat = new Vector2(1, 1);

    material.colorNode = uv().mul(texture);
    material.map = texture;
    material.needsUpdate = true;
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Attach no handlers; this is a static sprite
  group.userData.handlers = {};

  return group;
}
